def bfs(graph, start):
    found = {start}
    queue = deque([start])
    order = []
    while queue:
        v = queue.__1__()
        order.append(v)
        for n in sorted(graph.adjacency[v]):
            if n __2__ found:
                found.add(n)
                queue.append(n)
    return order
